double generate_gaussian(double mean, double sigma, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    // Generate two uniform random numbers using LCG
    seed = (a * seed + c) % m;
    double u1 = static_cast<double>(seed) / m;

    seed = (a * seed + c) % m;
    double u2 = static_cast<double>(seed) / m;

    // Apply Box-Muller transform
    // We need to ensure u1 is not zero to avoid log(0)
    if (u1 == 0.0) u1 = 1e-10;

    double z0 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);

    // Transform to desired mean and sigma
    return mean + z0 * sigma;
}

